CustomField.formula:
IF(ISPICKVAL(Payment_Type__c, 'Draft'), 'Escrow', 
    IF(ISPICKVAL(Payment_Type__c, 'Settlement'), 'Creditors', 
        IF(ISPICKVAL(Payment_Type__c, 'Program Fee'), 'Coastal Debt', 
            IF(ISPICKVAL(Payment_Type__c, 'Program Fee - Settlements'), 'Coastal Debt', 
                IF(ISPICKVAL(Payment_Type__c, 'Retainer Fee'), 'Coastal Debt',
                    IF(ISPICKVAL(Payment_Type__c, 'Setup Fee'), 'Citadel',  
                        IF(ISPICKVAL(Payment_Type__c, 'Processor Fee'), 'Payment Processor',
                            IF(ISPICKVAL(Payment_Type__c, 'Service Fee'), 'Coastal Debt',
                                IF(ISPICKVAL(Payment_Type__c, 'Citadel Fee'), 'Citadel',
                                    IF(ISPICKVAL(Payment_Type__c, 'Escrow Amount'), 'Escrow', '')
                                )
                            )
                        )
                    )
                )
            )
        )
    )
)
